describe('Product Sort by Price - Cheapest First', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.login('standard_user', 'secret_sauce');
  });

  it('should sort products by price in ascending order when selecting "lohi" option', () => {
    // Verify initial product list is displayed
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify initial sort option is not selected
    cy.get('[data-testid="product-sort-dropdown"]').should('contain', 'Price');

    // Verify "lohi" option is available
    cy.get('[data-testid="product-sort-dropdown"]').should('contain', 'Price');
    cy.get('[data-testid="product-sort-option-lohi"]').should('be.visible');

    // Click "lohi" option to sort by price
    cy.get('[data-testid="product-sort-option-lohi"]').click();

    // Verify sort state is updated
    cy.get('[data-testid="product-sort-dropdown"]').should('contain', 'Price');
    cy.get('[data-testid="product-sort-option-lohi"]').should('be.visible');

    // Verify products are now sorted by price in ascending order
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="product-item"]').first().should('contain', 'Price: $1');
    cy.get('[data-testid="product-item"]').last().should('contain', 'Price: $10');
  });

  it('should handle edge case where all products have the same price', () => {
    // Verify initial product list is displayed
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify initial sort option is not selected
    cy.get('[data-testid="product-sort-dropdown"]').should('contain', 'Price');

    // Click "lohi" option to sort by price
    cy.get('[data-testid="product-sort-option-lohi"]').click();

    // Verify sort state is updated
    cy.get('[data-testid="product-sort-dropdown"]').should('contain', 'Price');
    cy.get('[data-testid="product-sort-option-lohi"]').should('be.visible');

    // Verify products are still displayed in the same order (no change)
    cy.get('[data-testid="product-item"]').first().should('contain', 'Price: $1');
    cy.get('[data-testid="product-item"]').last().should('contain', 'Price: $1');
  });
});
